import{_ as t,o as n,c as s,a2 as i}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"3.2 触电类型与触电方式","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-2-chu-dian-lei-xing-yu-chu-dian-fang-shi.md","filePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-2-chu-dian-lei-xing-yu-chu-dian-fang-shi.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-2-chu-dian-lei-xing-yu-chu-dian-fang-shi.md"};function e(o,a,r,d,p,h){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="_3-2-触电类型与触电方式" tabindex="-1">3.2 触电类型与触电方式 <a class="header-anchor" href="#_3-2-触电类型与触电方式" aria-label="Permalink to &quot;3.2 触电类型与触电方式&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>人为什么会触电?按&quot;人和电源怎么接触&quot;来分,主要有<strong>单相触电、两相触电、跨步电压触电</strong>几种。这一节把每种触电的电流路径、危险程度讲清楚——知道了哪条路危险,才能知道怎么避开。</p><h2 id="一、触电事故的主要类型" tabindex="-1">一、触电事故的主要类型 <a class="header-anchor" href="#一、触电事故的主要类型" aria-label="Permalink to &quot;一、触电事故的主要类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>电流路径</th><th>危险程度</th><th>发生场合</th></tr></thead><tbody><tr><td><strong>单相触电</strong></td><td>一根火线 → 人体 → 大地</td><td>常见、较危险</td><td>触及带电的相线</td></tr><tr><td><strong>两相触电</strong></td><td>一根火线 → 人体 → 另一根火线</td><td><strong>最危险</strong></td><td>同时触及两根火线</td></tr><tr><td><strong>跨步电压触电</strong></td><td>两脚之间形成电压 → 电流经双腿</td><td>视电压而定</td><td>高压线落地附近</td></tr><tr><td><strong>接触电压触电</strong></td><td>触摸带故障电压的设备外壳</td><td>较危险</td><td>设备漏电外壳带电</td></tr></tbody></table><h2 id="二、单相触电-最常见的触电" tabindex="-1">二、单相触电(最常见的触电) <a class="header-anchor" href="#二、单相触电-最常见的触电" aria-label="Permalink to &quot;二、单相触电(最常见的触电)&quot;">​</a></h2><p>人体某一部位<strong>接触一根相线(火线)</strong>,电流从火线经人体流入大地(或经零线),构成回路。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>     火线(L) ──────● 人手</span></span>
<span class="line"><span>                      │ 人体</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>                      ▼</span></span>
<span class="line"><span>                     大地</span></span></code></pre></div><ul><li>在中性点直接接地的系统中,人体承受的电压接近<strong>相电压(220 V)</strong>,很危险;</li><li>占触电事故的大多数——因为日常工作接触最多的是单根相线。</li></ul><h2 id="三、两相触电-最危险的触电" tabindex="-1">三、两相触电(最危险的触电) <a class="header-anchor" href="#三、两相触电-最危险的触电" aria-label="Permalink to &quot;三、两相触电(最危险的触电)&quot;">​</a></h2><p>人体同时接触<strong>两根相线</strong>,电流从一根火线经人体流到另一根火线。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  火线L1 ──────● 左手</span></span>
<span class="line"><span>                   │ 人体(电流横穿胸部)</span></span>
<span class="line"><span>                   ▼</span></span>
<span class="line"><span>  火线L2 ──────● 右手</span></span></code></pre></div><ul><li>人体承受<strong>线电压(380 V)</strong>,比单相触电电压更高;</li><li>电流必然通过身体躯干,<strong>极易穿过心脏</strong>,致命风险最大。</li></ul><blockquote><p>⚠️ 重点:两相触电为什么最危险?两个原因——电压高(380V)+ 电流横穿心脏。</p></blockquote><h2 id="四、跨步电压触电" tabindex="-1">四、跨步电压触电 <a class="header-anchor" href="#四、跨步电压触电" aria-label="Permalink to &quot;四、跨步电压触电&quot;">​</a></h2><p><strong>高压线(或高压设备)断线落地点附近</strong>,大地表面会形成不同的电位。人走进危险区,两脚之间出现电位差(电压),电流从一只脚经两腿流到另一只脚,就是<strong>跨步电压触电</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       落地点(高压)</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>        ┌──┴──┐   ← 地面电位呈环形分布</span></span>
<span class="line"><span>        │      │</span></span>
<span class="line"><span>    脚A ●────● 脚B   ← 两脚之间形成电压</span></span>
<span class="line"><span>         电流经两腿</span></span></code></pre></div><p><strong>正确逃生姿势</strong>:发现高压线落地,<strong>双脚并拢跳跃</strong>或用单脚跳着离开危险区——让两脚电位尽量相同,避免形成跨步电压。</p><h2 id="五、接触电压触电" tabindex="-1">五、接触电压触电 <a class="header-anchor" href="#五、接触电压触电" aria-label="Permalink to &quot;五、接触电压触电&quot;">​</a></h2><p>电气设备外壳因绝缘损坏而带电(漏电),人<strong>触摸外壳</strong>时,电流经人体流入大地,称为接触电压触电。这就是为什么设备外壳要<strong>接地保护</strong>(第 11 章详讲)——外壳一旦接地,漏电电流直接流走,人触摸到时的接触电压就很小。</p><h2 id="六、其他触电形式-了解" tabindex="-1">六、其他触电形式(了解) <a class="header-anchor" href="#六、其他触电形式-了解" aria-label="Permalink to &quot;六、其他触电形式(了解)&quot;">​</a></h2><ul><li><strong>高压电弧触电</strong>:人距高压带电体太近,高压把空气击穿形成电弧,电流通过电弧伤人;</li><li><strong>感应电压触电</strong>:靠近高压线路的导体感应出电压,人接触时触电。</li></ul><h2 id="七、考点提示" tabindex="-1">七、考点提示 <a class="header-anchor" href="#七、考点提示" aria-label="Permalink to &quot;七、考点提示&quot;">​</a></h2><ul><li>✅ <strong>两相触电最危险</strong>(380 V + 电流穿胸)。</li><li>✅ <strong>单相触电最常见</strong>(220 V)。</li><li>✅ 高压线落地:双脚并拢跳跃逃离,避免跨步电压。</li><li>✅ 设备外壳漏电 → 接触电压触电 → 靠接地保护解决。</li><li>⚠️ 易混点:单相(一根火线对大地)与两相(两根火线之间)的区别,从&quot;电流路径&quot;理解。</li></ul><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><ul><li>触电分单相、两相、跨步电压、接触电压等类型。</li><li>单相最常见、两相最危险;跨步电压靠&quot;双脚并拢跳&quot;逃生。</li><li>接地保护能大大降低接触电压触电的风险。</li></ul><h2 id="九、自测练习" tabindex="-1">九、自测练习 <a class="header-anchor" href="#九、自测练习" aria-label="Permalink to &quot;九、自测练习&quot;">​</a></h2><ol><li>(单选)下列触电方式中,最危险的是()。 A. 单相触电　B. 两相触电　C. 接触电压触电　D. 感应电压触电</li><li>(判断)单相触电是最常见的触电方式。( )</li><li>(判断)发现高压线落地时,应当大步快速跑离危险区。( )</li><li>(单选)两相触电时,人体承受的电压接近于()。 A. 相电压　B. 线电压　C. 安全电压　D. 感应电压</li><li>(判断)设备外壳漏电时触摸外壳发生的触电,属于接触电压触电。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。两相触电电压高(380 V)且电流穿胸,最危险。</li><li><strong>√</strong>。单相触电在日常作业中发生率最高。</li><li><strong>×</strong>。应双脚并拢跳跃或单脚跳着离开,大步跑反而会形成跨步电压。</li><li><strong>B</strong>。两相触电承受线电压(380 V)。</li><li><strong>√</strong>。触摸带故障电压的外壳属于接触电压触电。</li></ol></details>`,29)])])}const u=t(l,[["render",e]]);export{g as __pageData,u as default};
